domain Real {
    function add(a: Real, b: Real): Real
    function sub(a: Real, b: Real): Real
    function mul(a: Real, b: Real): Real
    function div(a: Real, b: Real): Real
    function lt(a: Real, b: Real): Bool
    function leq(a: Real, b: Real): Bool
    function gt(a: Real, b: Real): Bool
    function geq(a: Real, b: Real): Bool
    function eq(a: Real, b: Real): Bool
    function neq(a: Real, b: Real): Bool
    function clamp(a: Real, min: Real, max: Real): Real
    function sqrt(a: Real): Real
    function isNan(a: Real): Bool
    function isInf(a: Real): Bool
    function inf(): Real
    function negInf(): Real
    function fromInt(i: Int): Real
    function toInt(r: Real): Int
    function max(a: Real, b: Real): Real
    function min(a: Real, b: Real): Real

    axiom add_comm { forall a: Real, b: Real :: add(a, b) == add(b, a) }
    axiom add_assoc { forall a: Real, b: Real, c: Real :: add(add(a, b), c) == add(a, add(b, c)) }
    axiom mul_comm { forall a: Real, b: Real :: mul(a, b) == mul(b, a) }
    axiom mul_assoc { forall a: Real, b: Real, c: Real :: mul(mul(a, b), c) == mul(a, mul(b, c)) }
    axiom distr { forall a: Real, b: Real, c: Real :: mul(a, add(b, c)) == add(mul(a, b), mul(a, c)) }
    axiom clamp_bounds { forall a: Real, min: Real, max: Real :: leq(min, clamp(a, min, max)) && leq(clamp(a, min, max), max) }
    axiom sqrt_nonneg { forall a: Real :: leq(0.0, a) ==> leq(0.0, sqrt(a)) }
}

domain Int {
    function add(a: Int, b: Int): Int
    function sub(a: Int, b: Int): Int
    function mul(a: Int, b: Int): Int
    function div(a: Int, b: Int): Int
    function mod(a: Int, b: Int): Int
    function lt(a: Int, b: Int): Bool
    function leq(a: Int, b: Int): Bool
    function gt(a: Int, b: Int): Bool
    function geq(a: Int, b: Int): Bool
    function eq(a: Int, b: Int): Bool
    function neq(a: Int, b: Int): Bool
    function max(a: Int, b: Int): Int
    function min(a: Int, b: Int): Int
    function toReal(i: Int): Real

    axiom add_comm { forall a: Int, b: Int :: add(a, b) == add(b, a) }
    axiom add_assoc { forall a: Int, b: Int, c: Int :: add(add(a, b), c) == add(a, add(b, c)) }
    axiom mul_comm { forall a: Int, b: Int :: mul(a, b) == mul(b, a) }
    axiom mul_assoc { forall a: Int, b: Int, c: Int :: mul(mul(a, b), c) == mul(a, mul(b, c)) }
    axiom distr { forall a: Int, b: Int, c: Int :: mul(a, add(b, c)) == add(mul(a, b), mul(a, c)) }
}

function stableHash(bytes: Seq[Int], seed: Int): Int
function popCount(i: Int): Int
function sliceAsBytes(s: Seq[Int]): Seq[Int]
function asBytes(i: Int): Seq[Int]
function memEql(a: Seq[Int], b: Seq[Int]): Bool

field ngram_weights: Seq[Real]
field lsh_hash_params: Seq[Int]
field num_hash_functions: Int
field num_ngrams: Int
field seed: Int
field allocator: Ref

field bits: Seq[Int]
field count: Int
field shape_dims: Seq[Int]
field data: Seq[Real]
field position: Int
field anchor: Bool
field score: Real
field tokens: Seq[Int]

predicate Ranker(r: Ref) {
    acc(r.ngram_weights) &&
    acc(r.lsh_hash_params) &&
    acc(r.num_hash_functions) &&
    acc(r.num_ngrams) &&
    acc(r.seed) &&
    acc(r.allocator)
}

predicate Tensor(t: Ref) {
    acc(t.shape_dims) &&
    acc(t.data)
}

predicate BitSet(b: Ref) {
    acc(b.bits) &&
    acc(b.count)
}

predicate RankedSegment(s: Ref) {
    acc(s.tokens) &&
    acc(s.score) &&
    acc(s.position) &&
    acc(s.anchor)
}

predicate SSI(s: Ref) {
    true
}

predicate AutoHashMap(h: Ref) {
    true
}

predicate PriorityQueue(q: Ref) {
    true
}

predicate ArrayList(l: Ref) {
    true
}

function RankerConfig_STREAMING_BUFFER_SIZE(): Int
function RankerConfig_STREAMING_WINDOW_SIZE(): Int
function RankerConfig_DEFAULT_TOP_K_RETRIEVAL(): Int
function RankerConfig_HASH_SEED_MULTIPLIER_A(): Int
function RankerConfig_HASH_SEED_MULTIPLIER_B(): Int
function RankerConfig_LEARNING_RATE(): Real
function RankerConfig_DIVERSITY_WEIGHT(): Real
function RankerConfig_PROXIMITY_WEIGHT(): Real
function RankerConfig_MAX_RAW_SCORE(): Real
function RankerConfig_BASE_SCORE_WEIGHT(): Real
function RankerConfig_OVERLAP_WEIGHT(): Real
function RankerConfig_JACCARD_WEIGHT(): Real

method Ranker_init(allocator: Ref, num_ngrams: Int, num_hash_funcs: Int, seed: Int) returns (r: Ref)
    requires num_ngrams > 0 && num_hash_funcs > 0
    ensures Ranker(r) && acc(r.ngram_weights) && acc(r.lsh_hash_params)
    ensures r.num_ngrams == num_ngrams && r.num_hash_functions == num_hash_funcs && r.seed == seed
{
    r := new(Ref)
    r.num_ngrams := num_ngrams
    r.num_hash_functions := num_hash_funcs
    r.seed := seed
    r.allocator := allocator

    var weights: Seq[Real] := Seq[Real](num_ngrams, _ => 0.0)
    var i: Int := 0
    while (i < num_ngrams)
        invariant 0 <= i && i <= num_ngrams
        invariant forall j: Int :: 0 <= j && j < i ==> weights[j] == Real_div(1.0, Real_fromInt(Int_add(j, 1)))
    {
        weights := weights.updated(i, Real_div(1.0, Real_fromInt(Int_add(i, 1))))
        i := Int_add(i, 1)
    }
    r.ngram_weights := weights

    var hash_params: Seq[Int] := Seq[Int](Int_mul(num_hash_funcs, 2), _ => 0)
    i := 0
    while (i < num_hash_funcs)
        invariant 0 <= i && i <= num_hash_funcs
        invariant forall j: Int :: 0 <= j && j < i ==>
            hash_params[Int_mul(j, 2)] == Int_add(seed, Int_mul(j, RankerConfig_HASH_SEED_MULTIPLIER_A())) &&
            hash_params[Int_add(Int_mul(j, 2), 1)] == Int_add(seed, Int_mul(Int_add(j, 1), RankerConfig_HASH_SEED_MULTIPLIER_B()))
    {
        hash_params := hash_params.updated(Int_mul(i, 2), Int_add(seed, Int_mul(i, RankerConfig_HASH_SEED_MULTIPLIER_A())))
        hash_params := hash_params.updated(Int_add(Int_mul(i, 2), 1), Int_add(seed, Int_mul(Int_add(i, 1), RankerConfig_HASH_SEED_MULTIPLIER_B())))
        i := Int_add(i, 1)
    }
    r.lsh_hash_params := hash_params
}

method Ranker_deinit(r: Ref)
    requires Ranker(r)
    ensures !acc(r.ngram_weights) && !acc(r.lsh_hash_params)
{
    fold acc(r.ngram_weights)
    fold acc(r.lsh_hash_params)
}

method scoreSequence(r: Ref, tokens: Seq[Int], ssi: Ref) returns (result: Real)
    requires Ranker(r) && acc(tokens)
    requires tokens != Seq
    ensures result >= 0.0 && result <= 1.0
{
    var ngram_score: Real := 0.0
    var gram: Int := 1
    while (gram < Int_min(r.num_ngrams, Int_add(tokens.length, 1)))
        invariant 1 <= gram && gram <= Int_min(r.num_ngrams, Int_add(tokens.length, 1))
        invariant ngram_score >= 0.0
    {
        if (tokens.length < gram) {
            gram := Int_add(gram, 1)
            continue
        }
        var start: Int := 0
        while (start < Int_sub(tokens.length, gram) + 1)
            invariant 0 <= start && start <= Int_sub(tokens.length, gram) + 1
            invariant ngram_score >= 0.0
        {
            var ngram: Seq[Int] := tokens[start .. Int_add(start, gram)]
            var h: Int := stableHash(sliceAsBytes(ngram), r.seed)
            if (SSI_getSegment(ssi, h)) {
                var weight_idx: Int := Int_min(Int_sub(gram, 1), Int_sub(r.ngram_weights.length, 1))
                ngram_score := Real_add(ngram_score, Real_mul(r.ngram_weights[weight_idx], SSI_getSegment_score(ssi, h)))
            }
            start := Int_add(start, 1)
        }
        gram := Int_add(gram, 1)
    }

    var diversity_score: Real := computeTokenDiversity(r, tokens)
    var proximity: Real := anchorProximity(r, tokens, ssi)

    var raw_score: Real := Real_add(ngram_score, Real_mul(RankerConfig_DIVERSITY_WEIGHT(), diversity_score))
    raw_score := Real_add(raw_score, Real_mul(RankerConfig_PROXIMITY_WEIGHT(), proximity))
    raw_score := Real_clamp(raw_score, 0.0, RankerConfig_MAX_RAW_SCORE())
    result := Real_div(raw_score, RankerConfig_MAX_RAW_SCORE())
}

method scoreSequenceWithQuery(r: Ref, tokens: Seq[Int], query: Seq[Int], ssi: Ref) returns (result: Real)
    requires Ranker(r) && acc(tokens) && acc(query)
    requires tokens != Seq
    ensures result >= 0.0 && result <= 1.0
{
    var base_score: Real := scoreSequence(r, tokens, ssi)
    var token_overlap: Real := computeTokenOverlap(r, tokens, query)
    var jaccard: Real := computeJaccardSimilarity(r, tokens, query)

    var combined_score: Real := Real_add(
        Real_mul(base_score, RankerConfig_BASE_SCORE_WEIGHT()),
        Real_mul(token_overlap, RankerConfig_OVERLAP_WEIGHT())
    )
    combined_score := Real_add(combined_score, Real_mul(jaccard, RankerConfig_JACCARD_WEIGHT()))
    result := Real_clamp(combined_score, 0.0, 1.0)
}

method computeTokenDiversity(r: Ref, tokens: Seq[Int]) returns (result: Real)
    requires Ranker(r) && acc(tokens)
    requires tokens != Seq
    ensures result >= 0.0 && result <= 1.0
{
    var unique_tokens := AutoHashMap_init(r.allocator)
    var i: Int := 0
    while (i < tokens.length)
        invariant 0 <= i && i <= tokens.length
        invariant AutoHashMap(unique_tokens)
    {
        AutoHashMap_put(unique_tokens, tokens[i], 0)
        i := Int_add(i, 1)
    }

    var unique_count: Int := AutoHashMap_count(unique_tokens)
    result := Real_div(Real_fromInt(unique_count), Real_fromInt(tokens.length))
    AutoHashMap_deinit(unique_tokens)
}

method computeTokenOverlap(r: Ref, tokens: Seq[Int], query: Seq[Int]) returns (result: Real)
    requires Ranker(r) && acc(tokens) && acc(query)
    requires tokens != Seq && query != Seq
    ensures result >= 0.0 && result <= 1.0
{
    var overlap: Int := 0
    var i: Int := 0
    while (i < tokens.length)
        invariant 0 <= i && i <= tokens.length
        invariant overlap >= 0
    {
        var j: Int := 0
        while (j < query.length)
            invariant 0 <= j && j <= query.length
            invariant overlap >= 0
        {
            if (tokens[i] == query[j]) {
                overlap := Int_add(overlap, 1)
                break
            }
            j := Int_add(j, 1)
        }
        i := Int_add(i, 1)
    }

    var max_len: Int := Int_max(tokens.length, query.length)
    result := Real_div(Real_fromInt(overlap), Real_fromInt(max_len))
}

method computeJaccardSimilarity(r: Ref, tokens: Seq[Int], query: Seq[Int]) returns (result: Real)
    requires Ranker(r) && acc(tokens) && acc(query)
    ensures result >= 0.0 && result <= 1.0
{
    if (tokens == Seq && query == Seq) {
        result := 1.0
        return
    }
    if (tokens == Seq || query == Seq) {
        result := 0.0
        return
    }

    var seen := AutoHashMap_init(r.allocator)
    var i: Int := 0
    while (i < tokens.length)
        invariant 0 <= i && i <= tokens.length
        invariant AutoHashMap(seen)
    {
        AutoHashMap_put(seen, tokens[i], 1)
        i := Int_add(i, 1)
    }

    i := 0
    while (i < query.length)
        invariant 0 <= i && i <= query.length
        invariant AutoHashMap(seen)
    {
        if (AutoHashMap_get(seen, query[i])) {
            AutoHashMap_put(seen, query[i], 2)
        } else {
            AutoHashMap_put(seen, query[i], 1)
        }
        i := Int_add(i, 1)
    }

    var intersection: Int := 0
    var union_size: Int := 0
    var it := AutoHashMap_iterator(seen)
    while (AutoHashMapIterator_next(it))
        invariant intersection >= 0 && union_size >= 0
    {
        union_size := Int_add(union_size, 1)
        if (AutoHashMapIterator_value(it) == 2) {
            intersection := Int_add(intersection, 1)
        }
    }

    if (union_size == 0) {
        result := 0.0
    } else {
        result := Real_div(Real_fromInt(intersection), Real_fromInt(union_size))
    }
    AutoHashMap_deinit(seen)
}

method anchorProximity(r: Ref, tokens: Seq[Int], ssi: Ref) returns (result: Real)
    requires Ranker(r) && acc(tokens)
    requires tokens != Seq
    ensures result >= 0.0 && result <= 1.0
{
    var anchors: Int := 0
    var total_dist: Real := 0.0
    var i: Int := 0
    while (i < tokens.length)
        invariant 0 <= i && i <= tokens.length
        invariant anchors >= 0
        invariant total_dist >= 0.0
    {
        var pos: Int := i
        if (SSI_getSegment(ssi, pos)) {
            if (SSI_getSegment_anchor_hash(ssi, pos) != 0) {
                anchors := Int_add(anchors, 1)
                var raw_dist: Int := if (i > SSI_getSegment_position(ssi, pos))
                    Int_sub(i, SSI_getSegment_position(ssi, pos))
                else
                    Int_sub(SSI_getSegment_position(ssi, pos), i)
                var clamped_dist: Int := Int_min(raw_dist, Int_max(0, 4294967295))
                total_dist := Real_add(total_dist, Real_fromInt(clamped_dist))
            }
        }
        i := Int_add(i, 1)
    }

    if (anchors == 0) {
        result := 0.0
    } else {
        var denominator: Int := Int_mul(anchors, tokens.length)
        var denom_clamped: Int := Int_min(denominator, 4294967295)
        var denom_f32: Real := Real_fromInt(Int_max(denom_clamped, 1))
        result := Real_sub(1.0, Real_clamp(Real_div(total_dist, denom_f32), 0.0, 1.0))
    }
}

method rankCandidates(r: Ref, candidates: Seq[Ref], ssi: Ref, allocator: Ref)
    requires Ranker(r) && acc(candidates)
    requires forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
    ensures forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
{
    if (candidates.length == 0) {
        return
    }

    var scores: Seq[Real] := Seq[Real](candidates.length, _ => 0.0)
    var i: Int := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==> scores[j] == scoreSequence(r, RankedSegment_tokens(candidates[j]), ssi)
    {
        scores := scores.updated(i, scoreSequence(r, RankedSegment_tokens(candidates[i]), ssi))
        i := Int_add(i, 1)
    }

    normalizeScoresStatic(scores)

    var indices: Seq[Int] := Seq[Int](candidates.length, _ => 0)
    i := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==> indices[j] == j
    {
        indices := indices.updated(i, i)
        i := Int_add(i, 1)
    }

    sortIndices(indices, scores)

    var sorted_tokens: Seq[Seq[Int]] := Seq[Seq[Int]](candidates.length, _ => Seq)
    var sorted_scores: Seq[Real] := Seq[Real](candidates.length, _ => 0.0)
    var sorted_positions: Seq[Int] := Seq[Int](candidates.length, _ => 0)
    var sorted_anchors: Seq[Bool] := Seq[Bool](candidates.length, _ => false)

    i := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==>
            sorted_tokens[j] == RankedSegment_tokens(candidates[indices[j]]) &&
            sorted_scores[j] == scores[indices[j]] &&
            sorted_positions[j] == RankedSegment_position(candidates[indices[j]]) &&
            sorted_anchors[j] == RankedSegment_anchor(candidates[indices[j]])
    {
        var src_idx: Int := indices[i]
        sorted_tokens := sorted_tokens.updated(i, RankedSegment_tokens(candidates[src_idx]))
        sorted_scores := sorted_scores.updated(i, scores[src_idx])
        sorted_positions := sorted_positions.updated(i, RankedSegment_position(candidates[src_idx]))
        sorted_anchors := sorted_anchors.updated(i, RankedSegment_anchor(candidates[src_idx]))
        i := Int_add(i, 1)
    }

    i := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==>
            RankedSegment_tokens(candidates[j]) == sorted_tokens[j] &&
            RankedSegment_score(candidates[j]) == sorted_scores[j] &&
            RankedSegment_position(candidates[j]) == sorted_positions[j] &&
            RankedSegment_anchor(candidates[j]) == sorted_anchors[j]
    {
        RankedSegment_set_tokens(candidates[i], sorted_tokens[i])
        RankedSegment_set_score(candidates[i], sorted_scores[i])
        RankedSegment_set_position(candidates[i], sorted_positions[i])
        RankedSegment_set_anchor(candidates[i], sorted_anchors[i])
        i := Int_add(i, 1)
    }
}

method rankCandidatesWithQuery(r: Ref, candidates: Seq[Ref], query: Seq[Int], ssi: Ref, allocator: Ref)
    requires Ranker(r) && acc(candidates) && acc(query)
    requires forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
    ensures forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
{
    if (candidates.length == 0) {
        return
    }

    var scores: Seq[Real] := Seq[Real](candidates.length, _ => 0.0)
    var i: Int := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==> scores[j] == scoreSequenceWithQuery(r, RankedSegment_tokens(candidates[j]), query, ssi)
    {
        scores := scores.updated(i, scoreSequenceWithQuery(r, RankedSegment_tokens(candidates[i]), query, ssi))
        i := Int_add(i, 1)
    }

    normalizeScoresStatic(scores)

    var indices: Seq[Int] := Seq[Int](candidates.length, _ => 0)
    i := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==> indices[j] == j
    {
        indices := indices.updated(i, i)
        i := Int_add(i, 1)
    }

    sortIndices(indices, scores)

    var sorted_tokens: Seq[Seq[Int]] := Seq[Seq[Int]](candidates.length, _ => Seq)
    var sorted_scores: Seq[Real] := Seq[Real](candidates.length, _ => 0.0)
    var sorted_positions: Seq[Int] := Seq[Int](candidates.length, _ => 0)
    var sorted_anchors: Seq[Bool] := Seq[Bool](candidates.length, _ => false)

    i := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==>
            sorted_tokens[j] == RankedSegment_tokens(candidates[indices[j]]) &&
            sorted_scores[j] == scores[indices[j]] &&
            sorted_positions[j] == RankedSegment_position(candidates[indices[j]]) &&
            sorted_anchors[j] == RankedSegment_anchor(candidates[indices[j]])
    {
        var src_idx: Int := indices[i]
        sorted_tokens := sorted_tokens.updated(i, RankedSegment_tokens(candidates[src_idx]))
        sorted_scores := sorted_scores.updated(i, scores[src_idx])
        sorted_positions := sorted_positions.updated(i, RankedSegment_position(candidates[src_idx]))
        sorted_anchors := sorted_anchors.updated(i, RankedSegment_anchor(candidates[src_idx]))
        i := Int_add(i, 1)
    }

    i := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant forall j: Int :: 0 <= j && j < i ==>
            RankedSegment_tokens(candidates[j]) == sorted_tokens[j] &&
            RankedSegment_score(candidates[j]) == sorted_scores[j] &&
            RankedSegment_position(candidates[j]) == sorted_positions[j] &&
            RankedSegment_anchor(candidates[j]) == sorted_anchors[j]
    {
        RankedSegment_set_tokens(candidates[i], sorted_tokens[i])
        RankedSegment_set_score(candidates[i], sorted_scores[i])
        RankedSegment_set_position(candidates[i], sorted_positions[i])
        RankedSegment_set_anchor(candidates[i], sorted_anchors[i])
        i := Int_add(i, 1)
    }
}

method batchScore(r: Ref, sequences: Seq[Seq[Int]], ssi: Ref, allocator: Ref) returns (scores: Seq[Real])
    requires Ranker(r) && acc(sequences)
    ensures scores.length == sequences.length
{
    if (sequences.length == 0) {
        scores := Seq
        return
    }

    scores := Seq[Real](sequences.length, _ => 0.0)
    var i: Int := 0
    while (i < sequences.length)
        invariant 0 <= i && i <= sequences.length
        invariant forall j: Int :: 0 <= j && j < i ==> scores[j] == scoreSequence(r, sequences[j], ssi)
    {
        scores := scores.updated(i, scoreSequence(r, sequences[i], ssi))
        i := Int_add(i, 1)
    }
}

method topKHeap(r: Ref, ssi: Ref, query: Seq[Int], k: Int, allocator: Ref) returns (result: Seq[Ref])
    requires Ranker(r) && acc(query)
    requires k >= 0
    ensures forall c: Ref :: 0 <= c && c < result.length ==> RankedSegment(result[c])
{
    if (k == 0) {
        result := Seq
        return
    }

    var heap := PriorityQueue_init(allocator)
    var candidates := SSI_retrieveTopK(ssi, query, RankerConfig_DEFAULT_TOP_K_RETRIEVAL(), allocator)

    var i: Int := 0
    while (i < candidates.length)
        invariant 0 <= i && i <= candidates.length
        invariant PriorityQueue(heap)
        invariant forall c: Ref :: 0 <= c && c < candidates.length ==> RankedSegment(candidates[c])
    {
        var cand := candidates[i]
        var score: Real := scoreSequenceWithQuery(r, RankedSegment_tokens(cand), query, ssi)

        if (!Real_isNan(score) && !Real_isInf(score)) {
            if (PriorityQueue_count(heap) < k) {
                var ranked := RankedSegment_init(allocator, RankedSegment_tokens(cand), score, RankedSegment_position(cand), RankedSegment_anchor(cand))
                PriorityQueue_add(heap, ranked)
            } else if (PriorityQueue_peek(heap)) {
                var top := PriorityQueue_peek(heap)
                if (score > RankedSegment_score(top)) {
                    var removed := PriorityQueue_remove(heap)
                    RankedSegment_deinit(removed, allocator)
                    var ranked := RankedSegment_init(allocator, RankedSegment_tokens(cand), score, RankedSegment_position(cand), RankedSegment_anchor(cand))
                    PriorityQueue_add(heap, ranked)
                }
            }
        }
        i := Int_add(i, 1)
    }

    var result_count: Int := PriorityQueue_count(heap)
    result := Seq[Ref](result_count, _ => null)

    var idx: Int := result_count
    while (PriorityQueue_removeOrNull(heap))
        invariant idx >= 0 && idx <= result_count
        invariant PriorityQueue(heap)
    {
        var item := PriorityQueue_removeOrNull(heap)
        if (idx > 0) {
            idx := Int_sub(idx, 1)
            result := result.updated(idx, item)
        } else {
            RankedSegment_deinit(item, allocator)
        }
    }
}

method updateWeights(r: Ref, gradients: Seq[Real])
    requires Ranker(r) && acc(gradients)
    ensures Ranker(r)
{
    var i: Int := 0
    while (i < Int_min(r.ngram_weights.length, gradients.length))
        invariant 0 <= i && i <= Int_min(r.ngram_weights.length, gradients.length)
        invariant forall j: Int :: 0 <= j && j < i ==>
            !Real_isNan(gradients[j]) && !Real_isInf(gradients[j]) ==>
            r.ngram_weights[j] == Real_add(old(r.ngram_weights[j]), Real_mul(gradients[j], RankerConfig_LEARNING_RATE()))
    {
        var grad := gradients[i]
        if (!Real_isNan(grad) && !Real_isInf(grad)) {
            r.ngram_weights := r.ngram_weights.updated(i, Real_add(r.ngram_weights[i], Real_mul(grad, RankerConfig_LEARNING_RATE())))
            r.ngram_weights := r.ngram_weights.updated(i, Real_clamp(r.ngram_weights[i], 0.0, 1.0))
