        var crit_score: Real := 0.0
        var cr: Int := 0
        while (cr < num_crit)
            invariant 0 <= cr && cr <= num_crit
            invariant crit_score >= 0.0
        {
            if (c < criteria[cr].length) {
                var score_val: Real := criteria[cr][c]
                var weight_val: Real := weights[cr]
                if (!Real_isNan(score_val) && !Real_isNan(weight_val) && !Real_isInf(score_val) && !Real_isInf(weight_val)) {
                    crit_score := Real_add(crit_score, Real_mul(score_val, weight_val))
                }
            }
            cr := Int_add(cr, 1)
        }
        combined := combined.updated(c, crit_score)
        c := Int_add(c, 1)
    }

    var indices: Seq[Int] := Seq[Int](num_cand, _ => 0)
    var i: Int := 0
    while (i < num_cand)
        invariant 0 <= i && i <= num_cand
        invariant forall j: Int :: 0 <= j && j < i ==> indices[j] == j
