        i := Int_add(i, 1)
    }
}

method streamingRank(r: Ref, reader: Ref, ssi: Ref, k: Int, allocator: Ref) returns (result: Seq[Ref])
    requires Ranker(r) && k >= 0
    ensures forall c: Ref :: 0 <= c && c < result.length ==> RankedSegment(result[c])
{
    if (k == 0) {
        result := Seq
        return
    }

    var rolling_buffer := ArrayList_init(allocator)
    var top_k := ArrayList_init(allocator)
    var read_buffer: Seq[Int] := Seq[Int](RankerConfig_STREAMING_BUFFER_SIZE(), _ => 0)
    var position: Int := 0

    while (true)
        invariant ArrayList(rolling_buffer) && ArrayList(top_k)
        invariant position >= 0
    {
        var bytes_read: Int := read(reader, read_buffer)
        if (bytes_read == 0) {
            break
        }

        var tokens_read: Int := Int_div(bytes_read, 4)
        if (tokens_read == 0) {
            continue
        }

        var token_bytes: Seq[Int] := read_buffer[0 .. Int_mul(tokens_read, 4)]
        var tokens_slice: Seq[Int] := bytesAsSlice(token_bytes)

        var i: Int := 0
        while (i < tokens_slice.length)
            invariant 0 <= i && i <= tokens_slice.length
            invariant ArrayList(rolling_buffer)
        {
            ArrayList_append(rolling_buffer, tokens_slice[i])
            i := Int_add(i, 1)
        }

        while (ArrayList_length(rolling_buffer) >= RankerConfig_STREAMING_WINDOW_SIZE())
            invariant ArrayList(rolling_buffer) && ArrayList(top_k)
            invariant position >= 0
        {
            var window: Seq[Int] := ArrayList_items(rolling_buffer)[0 .. RankerConfig_STREAMING_WINDOW_SIZE()]
            var score: Real := scoreSequence(r, window, ssi)

            if (!Real_isNan(score) && !Real_isInf(score)) {
                if (ArrayList_length(top_k) < k) {
                    var seg := RankedSegment_init(allocator, window, score, position, false)
                    ArrayList_append(top_k, seg)
                } else {
                    var min_idx: Int := 0
                    var min_score: Real := RankedSegment_score(ArrayList_items(top_k)[0])
                    var j: Int := 1
                    while (j < ArrayList_length(top_k))
                        invariant 1 <= j && j <= ArrayList_length(top_k)
                        invariant min_score == minScore(ArrayList_items(top_k), j)
                    {
                        if (RankedSegment_score(ArrayList_items(top_k)[j]) < min_score) {
                            min_score := RankedSegment_score(ArrayList_items(top_k)[j])
                            min_idx := j
                        }
                        j := Int_add(j, 1)
                    }

                    if (score > min_score) {
                        RankedSegment_deinit(ArrayList_items(top_k)[min_idx], allocator)
                        ArrayList_items(top_k)[min_idx] := RankedSegment_init(allocator, window, score, position, false)
                    }
                }
            }

            ArrayList_orderedRemove(rolling_buffer, 0)
            position := Int_add(position, 1)
        }
    }

    sortRankedSegments(ArrayList_items(top_k))

    result := Seq[Ref](ArrayList_length(top_k), _ => null)
    i := 0
    while (i < ArrayList_length(top_k))
        invariant 0 <= i && i <= ArrayList_length(top_k)
        invariant forall j: Int :: 0 <= j && j < i ==> RankedSegment(result[j])
    {
        result := result.updated(i, RankedSegment_init(allocator,
            RankedSegment_tokens(ArrayList_items(top_k)[i]),
            RankedSegment_score(ArrayList_items(top_k)[i]),
            RankedSegment_position(ArrayList_items(top_k)[i]),
            RankedSegment_anchor(ArrayList_items(top_k)[i])))
        i := Int_add(i, 1)
    }
}

