                scores[i] := 0.5
            }
            i := Int_add(i, 1)
        }
        return
    }

    var range: Real := Real_sub(max_score, min_score)
    i := 0
    while (i < scores.length)
        invariant 0 <= i && i <= scores.length
    {
        if (!Real_isNan(scores[i]) && !Real_isInf(scores[i])) {
